import chalk from 'chalk'
import { inspect } from 'node:util'
import type { Logger } from '@servicenow/sdk-build-core'

export type LogLevel = 'debug' | 'info' | 'warn' | 'error' | 'silent'

const LEVEL_RANK: Record<LogLevel, number> = {
    debug: 10,
    info: 20,
    warn: 30,
    error: 40,
    silent: 100,
}

function formatArgs(args: unknown[], showStack: boolean): string {
    return args
        .map((arg) => {
            if (arg instanceof Error) {
                if (showStack) {
                    return inspect(arg)
                }
                const { cause } = arg
                return cause instanceof Error ? `${arg.message}\n  Caused by: ${cause.message}` : arg.message
            }
            if (typeof arg === 'object' && arg !== null) {
                try {
                    return JSON.stringify(arg)
                } catch {
                    return String(arg)
                }
            }
            return String(arg)
        })
        .join(' ')
}

class CLILogger implements Logger {
    private level: LogLevel = 'info'
    private useStderr = false

    constructor() {
        const envLevel = process.env['LOG_LEVEL']
        if (envLevel && envLevel in LEVEL_RANK) {
            this.level = envLevel as LogLevel
            this.info(`Setting log level to ${this.level} from process.env.LOG_LEVEL`)
        }
    }

    public setLevel(level: LogLevel): void {
        this.level = level
    }

    public setStream(target: 'stdout' | 'stderr'): void {
        this.useStderr = target === 'stderr'
    }

    public info(...args: unknown[]): void {
        if (!this.isEnabled('info')) {
            return
        }
        this.emit(`[now-sdk] ${formatArgs(args, false)}`)
    }

    public warn(...args: unknown[]): void {
        if (!this.isEnabled('warn')) {
            return
        }
        this.emit(chalk.yellow(`[now-sdk] WARN: ${formatArgs(args, false)}`))
    }

    public error(...args: unknown[]): void {
        if (!this.isEnabled('error')) {
            return
        }
        this.emit(chalk.red(`[now-sdk] ERROR: ${formatArgs(args, this.level === 'debug')}`))
    }

    public debug(...args: unknown[]): void {
        if (!this.isEnabled('debug')) {
            return
        }
        this.emit(`[now-sdk] DEBUG: ${formatArgs(args, true)}`)
    }

    // Defaults to stdout for backwards compatibility with tools that capture stdout from the CLI due to usage of Winston in the past logging to stdout instead of stderr.
    private emit(line: string): void {
        if (this.useStderr) {
            process.stderr.write(`${line}\n`)
        } else {
            console.log(line)
        }
    }

    private isEnabled(level: Exclude<LogLevel, 'silent'>): boolean {
        return LEVEL_RANK[level] >= LEVEL_RANK[this.level]
    }
}

export const logger = new CLILogger()
